#include <Raven.h>

typedef struct Dot { float x, y; int inside; RSpring sx, sy; } Dot;

/* the size the widget asks for */
static void measure(Rid w, float* width, float* height, void* user) {
	*width = 400.0f;
	*height = 300.0f;
}

/* called each time the widget is drawn: (0, 0) is its top-left corner */
static void paint(Rid w, RPainter* p, float width, float height, void* user) {
	Dot* d = user;
	float t = (float)Rget_time();

	Rdraw_rect(p, 0, 0, width, height, 12, 0.08f, 0.09f, 0.20f, 1);        /* x y w h radius rgba */
	Rdraw_line(p, 0, height / 2, width, height / 2, 1, 1, 1, 1, 0.1f);    /* x0 y0 x1 y1 thickness rgba */
	Rdraw_curve(p, 0, 200, 120, 200 - 60 * sinf(t), 280, 200 + 60 * cosf(t), width, 200,
		3, 0.4f, 0.8f, 1, 1);                                              /* a cubic bezier */
	Rdraw_triangle(p, 40, 40, 80, 40, 60, 75, 1, 0.4f, 0.4f, 1);
	Rdraw_text(p, R_INVALID_ID, 14, 16, 12, "Hello, canvas", 1, 1, 1, 0.8f);

	/* springs: the disc catches up with the pointer, overshoots, settles */
	float x = Rdraw_spring(p, &d->sx, d->x, R_MOTION_WOBBLY);
	float y = Rdraw_spring(p, &d->sy, d->y, R_MOTION_WOBBLY);
	Rdraw_circle(p, x, y, 10, 1, 0.27f, 0.35f, 1);

	Rwidget_invalidate(w);   /* draw again next frame: an animation */
}

static int event(Rid w, const REvent* e, void* user) {
	Dot* d = user;
	if (e->type == R_EVENT_MOUSE_MOVE) { d->x = e->local_x; d->y = e->local_y; }
	return R_FALSE;          /* R_TRUE would consume it */
}

static Rid create(const char* tag, void* user) {
	Rid w = Rwidget_create(R_WIDGET_CUSTOM);
	Dot* d = calloc(1, sizeof(Dot));
	Rcustom_set_measure_callback(w, measure, d);
	Rcustom_set_paint_callback(w, paint, d);
	Rwidget_set_event_callback(w, event, d);
	return w;
}

/* before loading the XML: <MyCanvas Height="300"/> is now a tag */
Rxml_register_tag("MyCanvas", create, NULL, NULL);
